const summary2 = flow('LR', [['a', 'Sum and difference'], ['b', r`Double angle: $y = x$`], ['c', r`Triple angle: $3x = 2x + x$`], ['d', 'Equations: general solutions']], [['a', 'b'], ['b', 'c'], ['c', 'd']], 'Summary flow: the sum and difference formulae give the double angle formulae by putting y equal x; the triple angle formulae come from writing 3x as 2x plus x; and general solutions describe all solutions of trigonometric equations.', 'Everything follows from the sum formulae.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Trigonometric Functions — Part 1: Angles, the unit circle and graphs',
  goals: ['Convert angles between degrees and radians', 'Use the arc-length formula l = r times theta', 'Define sine, cosine and tangent on the unit circle and give their signs', 'Sketch and read the graphs of sine, cosine and tangent', 'Reduce angles with the allied-angle rules'],
  slides: [
    sl('title', 'Trigonometric Functions, Part 1: Angles and the unit circle', { b: 'A point goes round a circle. Where is it after a given turn? That question is trigonometry.', v: titleCircle, n: 'Picture a point travelling round a circle. After it has turned through some angle, how far across is it, and how high? Those two numbers are the cosine and the sine of the angle. In this part you will measure turns in degrees and radians, define the three functions on the unit circle, learn their signs, and draw their graphs.' }),
    sl('concept', 'What you will be able to do', { ul: ['Convert between **degrees** and **radians**', 'Use **arc length** $l = r\\theta$', 'Define $\\sin$, $\\cos$, $\\tan$ on the **unit circle**; know the **signs** by quadrant', 'Read **domain, range and period**; sketch the **graphs**', 'Use **allied angles** such as $\\sin(\\pi - x)$'], n: 'Here are your goals for part one. You will convert between degrees and radians, use the arc length formula, and define sine, cosine and tangent on the unit circle. You will know their signs in each quadrant, their domains, ranges and periods, and the shapes of their graphs. Last, you will reduce large and negative angles with the allied angle rules.' }),
    sl('concept', 'Turns, degrees and radians', { b: 'A full turn is $360^\\circ$. The **radian** is the other unit: a full turn is $2\\pi$ radians, so a half turn is $\\pi$ radians.', v: tTurns, m: [r`\pi \text{ radians} = 180^\circ`], n: 'There are two units for angles. In degrees, a full turn is three hundred and sixty. In radians, a full turn is two pi, so a half turn is pi. The table lists the four quarter-turn rotations in both units. The key fact to remember is that pi radians equals one hundred and eighty degrees. Everything else follows from it.' }),
    sl('diagram', 'What is a radian?', { b: 'One **radian** is the angle at the centre of a circle that cuts off an arc **as long as the radius**. It is about $57.3^\\circ$.', v: oneRad, n: 'Take a circle and lay a piece of string, as long as the radius, along its edge. The angle at the centre that this arc subtends is one radian. It is a little more than fifty-seven degrees. Because the circumference is two pi times the radius, exactly two pi such arcs fit round the circle, which is why a full turn is two pi radians.' }),
    sl('concept', 'Converting between the units', { b: 'Radians $= $ degrees $\\times \\dfrac{\\pi}{180}$ and degrees $= $ radians $\\times \\dfrac{180}{\\pi}$. Learn the common pairs.', v: tConv, m: [r`\text{radian} = \text{degree} \times \dfrac{\pi}{180}`, r`\text{degree} = \text{radian} \times \dfrac{180}{\pi}`], n: 'To convert degrees to radians, multiply by pi over one hundred and eighty. To convert radians to degrees, multiply by one hundred and eighty over pi. The table gives the common pairs. Thirty degrees is pi over six, forty-five is pi over four, sixty is pi over three, ninety is pi over two, and one hundred and eighty is pi. Learn these by heart.' }),
    sl('check', 'Quick check: degrees to radians', { b: 'Convert one hundred and thirty-five degrees to radians.', chk: 'm02', n: 'Multiply by pi over one hundred and eighty and simplify the fraction.' }),
    sl('example', 'Worked example 1: conversions', { b: r`Convert $75^\circ$ and $-135^\circ$ to radians, and $\dfrac{7\pi}{10}$ rad and $2$ rad to degrees.`, ul: [r`**Degrees to radians —** multiply by $\dfrac{\pi}{180}$: $75^\circ = \dfrac{5\pi}{12}$, $-135^\circ = -\dfrac{3\pi}{4}$`, r`**Radians to degrees —** multiply by $\dfrac{180}{\pi}$: $\dfrac{7\pi}{10}$ rad $= 126^\circ$`, r`**Plain numbers —** $2$ rad $= 2 \times \dfrac{180}{3.14159} \approx 114.59^\circ$`], v: we1, n: 'For seventy-five degrees, multiply by pi over one hundred and eighty and cancel the common factor fifteen: five pi over twelve. Minus one hundred and thirty-five degrees gives minus three pi over four. For seven pi over ten radians, multiply by one hundred and eighty over pi; the pi cancels and you get one hundred and twenty-six degrees. A plain number such as two radians needs a decimal value of pi.' }),
    sl('concept', 'Arc length', { b: r`On a circle of radius $r$, an arc that subtends the angle $\theta$ **radians** at the centre has length $l = r\theta$. In degrees, first convert.`, v: arcFig, m: [r`l = r\theta`], n: 'The arc length formula is the reason radians are used. The angle theta, measured in radians, tells how many radius-lengths of arc fit. So the arc length is the radius times theta. This works only when theta is in radians. If the angle is given in degrees, convert it first, or the answer will be wrong by a large factor.' }),
    sl('example', 'Worked example 2: a curved flower bed', { b: r`An imagined flower bed has radius $7$ m. A curved edge subtends $100^\circ$ at the centre. Find its length.`, ul: [r`**Convert —** $100^\circ = \dfrac{5\pi}{9}$ radians`, r`**Apply $l = r\theta$ —** $l = 7 \times \dfrac{5\pi}{9} = \dfrac{35\pi}{9}$ m`, r`**Decimal —** $l \approx 12.22$ m`], v: we2, n: 'The angle is in degrees, so convert first: one hundred degrees is five pi over nine radians. Now multiply by the radius, seven metres. The arc length is thirty-five pi over nine metres, which is about twelve point two two metres. Keep the exact form in your working and give the decimal at the end.' }),
    sl('check', 'Quick check: angle from an arc', { b: 'An arc of nine centimetres on a circle of radius six centimetres: what is the angle in radians?', chk: 'm05', n: 'Rearrange the arc length formula for theta, then divide.' }),
    sl('concept', 'The unit circle definition', { b: r`On the **unit circle** (radius $1$, centre at the origin), the point reached after turning $\theta$ from the positive $x$-axis is $P(\theta) = (\cos\theta,\ \sin\theta)$. Also $\tan\theta = \dfrac{\sin\theta}{\cos\theta}$.`, v: circle120, m: [r`\sin^2\theta + \cos^2\theta = 1`], n: 'Here is the modern definition. Take the circle of radius one centred at the origin. Turn through an angle theta from the positive horizontal axis, anticlockwise for positive angles. The point you reach has horizontal coordinate cosine theta and vertical coordinate sine theta. Tangent is sine divided by cosine. Since the point is on the circle, sine squared plus cosine squared is one.' }),
    sl('diagram', 'Signs in the four quadrants', { b: r`The signs follow the coordinates of $P$: **All** positive in quadrant I, **S**ine in II, **T**angent in III, **C**osine in IV.`, v: quadFig, n: 'The signs depend on where the point lands. In the first quadrant both coordinates are positive, so all three functions are positive. In the second quadrant only the vertical coordinate, the sine, is positive. In the third quadrant both coordinates are negative, so tangent, their ratio, is positive. In the fourth quadrant only the horizontal coordinate, the cosine, is positive.' }),
    sl('check', 'Quick check: which quadrant?', { b: 'Sine is positive and tangent is negative. In which quadrant is the angle?', chk: 'm06', n: 'Sine positive leaves two quadrants. Which of them has a negative cosine?' }),
    sl('concept', 'Values at the standard angles', { b: 'Learn the exact values at $0^\\circ, 30^\\circ, 45^\\circ, 60^\\circ, 90^\\circ$; others follow from signs and symmetry.', v: tStd, n: 'This table gives the exact values at the standard angles. Sine rises from zero through one half, root two over two and root three over two to one. Cosine does the reverse. Tangent is sine over cosine, and it is not defined where the cosine is zero, at ninety and two hundred and seventy degrees. Larger angles use the same values with the sign from the quadrant.' }),
    sl('example', 'Worked example 3: all six ratios', { b: r`If $\sin\theta = -\dfrac{11}{61}$ and $\theta$ lies in the third quadrant, find the other five ratios.`, ul: [r`**Cosine —** $\cos^2\theta = 1 - \dfrac{121}{3721} = \dfrac{3600}{3721}$; negative in quadrant III: $-\dfrac{60}{61}$`, r`**Tangent —** $\dfrac{-11/61}{-60/61} = \dfrac{11}{60}$`, r`**Reciprocals —** $\operatorname{cosec}\theta = -\dfrac{61}{11}$, $\sec\theta = -\dfrac{61}{60}$, $\cot\theta = \dfrac{60}{11}$`], v: we3, n: 'First find the cosine from sine squared plus cosine squared equals one. The square is three thousand six hundred over three thousand seven hundred and twenty-one, so the size is sixty over sixty-one. The third quadrant has negative cosine, so it is minus sixty over sixty-one. Tangent is the ratio, eleven over sixty, positive. The other three are reciprocals of sine, cosine and tangent.' }),
    sl('concept', 'The graph of sine', { b: r`Sine takes every value in $[-1, 1]$, repeats every $2\pi$, is **odd**, and is $0$ at $x = n\pi$.`, v: pSin, n: 'The sine graph is a smooth wave. It starts at zero, rises to one at pi over two, returns to zero at pi, drops to minus one at three pi over two and comes back to zero at two pi. Then it repeats. The wave is odd: its left half is the right half turned upside down about the origin. All the zeros are at whole-number multiples of pi.' }),
    sl('concept', 'The graph of cosine', { b: r`Cosine is the sine wave shifted: range $[-1, 1]$, period $2\pi$, **even**, and $0$ at $x = \dfrac{\pi}{2} + n\pi$.`, v: pCos, n: 'The cosine graph has the same shape as sine, started at its peak. At zero it equals one. It reaches zero at pi over two, minus one at pi, zero at three pi over two and one again at two pi. Cosine is even, so the graph is a mirror image across the vertical axis. Its zeros are at odd multiples of pi over two.' }),
    sl('concept', 'The graph of tangent', { b: r`Tangent has period $\pi$, is **odd**, takes **every** real value, and breaks at $x = \dfrac{\pi}{2} + n\pi$ where $\cos x = 0$.`, v: pTan, n: 'The tangent graph consists of separate branches. Each branch rises from very large negative values to very large positive values. Between the dashed lines, which sit at odd multiples of pi over two, the branch crosses the axis at a multiple of pi and passes through pi over four, one. The pattern repeats every pi, and the range is all real numbers.' }),
    sl('concept', 'Domain, range, period, parity', { b: 'Summary of the three functions. The **period** is the smallest positive shift that leaves the function unchanged.', v: tProps, n: 'Here are the properties side by side. Sine and cosine are defined for every real number, take values between minus one and one, and have period two pi. Sine is odd and cosine is even. Tangent is not defined at odd multiples of pi over two, takes every real value, has the shorter period pi, and is odd. These facts are the basis of most questions on graphs.' }),
    sl('check', 'Quick check: cosine of a larger angle', { b: 'Find the value of cosine of five pi over three.', chk: 'm08', n: 'Convert to degrees, find the quadrant and the reference angle.' }),
    sl('diagram', 'Allied angles from symmetry', { b: r`The points $P(x)$ and $P(\pi - x)$ are mirror images in the $y$-axis, so $\sin(\pi - x) = \sin x$ and $\cos(\pi - x) = -\cos x$. Similar pictures give the other rules.`, v: allied, n: 'Allied angles are angles that differ from x by a multiple of a quarter turn, or are the negative of x. Take x and pi minus x. The two points are mirror images in the vertical axis. They have the same height, so the sines are equal, and opposite horizontal positions, so the cosines have opposite signs. In the same way you can read off the rules for pi plus x, two pi minus x, and minus x.' }),
    sl('example', 'Worked example 4: reducing angles', { b: r`Find $\sin 150^\circ$, $\cos 240^\circ$, $\tan 315^\circ$ and $\sin(-210^\circ)$ exactly.`, ul: [r`**Reference angle —** the acute angle to the nearest horizontal axis`, r`**Sign —** from the quadrant of the original angle`, r`**Values —** $\dfrac{1}{2},\ -\dfrac{1}{2},\ -1,\ \dfrac{1}{2}$`], v: we4, n: 'For each angle, find the reference angle, which is the acute angle to the horizontal axis, and then give the sign from the quadrant. One hundred and fifty degrees is in the second quadrant with reference angle thirty: sine is one half. Two hundred and forty has cosine minus one half. Three hundred and fifteen has tangent minus one. Minus two hundred and ten degrees lands in the second quadrant, so its sine is one half.' }),
    sl('check', 'Quick check: a sine of a negative angle', { b: 'What is the value of sine of minus pi over six?', chk: 'fb4', n: 'Sine is odd. What does that say about the sign?' }),
    sl('summary', 'Summary', { ul: [r`$180^\circ = \pi$ rad; arc length $l = r\theta$ ($\theta$ in radians)`, r`$P(\theta) = (\cos\theta, \sin\theta)$; signs by quadrant (All, Sine, Tangent, Cosine)`, r`Periods: $2\pi, 2\pi, \pi$; sine and tangent odd, cosine even`, r`Ranges: $[-1, 1]$, $[-1, 1]$, $\mathbb{R}$; tangent breaks at $\dfrac{\pi}{2} + n\pi$`, 'Allied angles: reference angle, then the sign from the quadrant'], v: summary1, n: 'To sum up. A half turn is pi radians. Arc length is the radius times the angle in radians. On the unit circle, cosine and sine are the coordinates of the point, and the signs follow the quadrants. Sine and cosine have period two pi, tangent has period pi. Sine and tangent are odd, cosine is even. Allied angles reduce to a reference angle with a sign from the quadrant.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Conversion (1 mark):** correct factor and simplified fraction', '**Arc length (2–3 marks):** convert to radians, formula, units', '**Signs and exact values (2–3 marks):** quadrant, reference angle, sign', '**Graph (2 marks):** shape, zeros, peaks, period', '**Mistake:** using $l = r\\theta$ with $\\theta$ in degrees', '**Mistake:** a wrong sign in quadrants II and III, or the period of $\\tan$ as $2\\pi$'], n: 'For conversion questions, show the factor and simplify the fraction. For arc lengths, convert to radians first, state the formula and give units. For exact values, name the quadrant, the reference angle and the sign. For graphs, mark the zeros, the peaks and the period. Three common slips: using degrees in the arc length formula, a wrong sign in the second or third quadrant, and giving the tangent a period of two pi.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Trigonometric Functions — Part 2: Sum, difference and multiple angle formulae',
  goals: ['Prove and use the sum and difference formulae', 'Find exact values at angles such as 15 and 75 degrees', 'Use the double and triple angle formulae', 'Prove simple identities from these formulae', 'Find general solutions of simple equations (formative)'],
  slides: [
    sl('title', 'Trigonometric Functions, Part 2: Compound and multiple angles', { b: 'Knowing sine and cosine of two angles, can we find those of their sum?', v: roadmap, n: 'In part one you learned the values at the standard angles. But what is the sine of seventy-five degrees, or of three times an angle? In this part, one idea answers every such question: the cosine of a difference. From it come the sum and difference formulae, then the double and triple angle formulae, and finally the general solutions of simple equations.' }),
    sl('concept', 'What you will be able to do', { ul: ['Derive $\\cos(x - y)$ from the **unit circle**', 'Use the six **sum and difference** formulae', 'Find exact values such as $\\sin 15^\\circ$', 'Use **double** and **triple angle** formulae', 'Solve simple equations: **general solutions** (formative)'], n: 'Here are your goals. You will see where the formula for the cosine of a difference comes from, and use all six sum and difference formulae. You will find exact values at fifteen and seventy-five degrees, use the double and triple angle formulae, and prove identities. Finally, general solutions of simple equations are included for understanding; they are not assessed in the annual paper.' }),
    sl('diagram', 'Where cos(x − y) comes from', { b: r`The chords $AB$ and $XC$ both subtend $x - y$ at the centre, so they are equal. Writing their lengths with coordinates gives $\cos(x - y) = \cos x\cos y + \sin x\sin y$.`, v: chordFig, m: [r`\cos(x - y) = \cos x\cos y + \sin x\sin y`], n: 'Place two points on the unit circle at angles x and y. The chord between them subtends the angle x minus y at the centre. Another chord, from the starting point to the point at angle x minus y, subtends the same angle, so it has the same length. Write both lengths with the distance formula, expand, and simplify using sine squared plus cosine squared equals one. The result is the formula for the cosine of a difference.' }),
    sl('concept', 'The six sum and difference formulae', { b: r`Replace $y$ by $-y$ for $\cos(x + y)$, then use $\sin\left(\dfrac{\pi}{2} - \theta\right) = \cos\theta$ for the sine formulae. Divide sine by cosine for tangent.`, v: tSum, n: 'From the cosine of a difference you get the other five. Replacing y by minus y gives the cosine of a sum. Using the rule that sine of pi over two minus theta is cosine theta gives the sine formulae. Dividing sine by cosine gives the tangent formulae. The table checks every formula at fifty and twenty degrees, and each pair of numbers agrees.' }),
    sl('concept', 'The tangent formulae and when they hold', { b: 'The tangent formulae divide by $1 \\mp \\tan x\\tan y$, so they are valid only when every tangent involved is **defined** and the denominator is **not zero**.', v: tTanCond, n: 'The tangent formulae have conditions. The tangents of x, y and of the sum or difference must all exist, which means none of the angles is an odd multiple of pi over two. The denominator must also not be zero. If the denominator is zero, the sum is an odd multiple of pi over two, where the tangent is not defined at all.' }),
    sl('check', 'Quick check: expanding a cosine', { b: 'Which expression equals the cosine of x plus y?', chk: 'm16', n: 'Remember the minus sign for the cosine of a sum.' }),
    sl('example', 'Worked example 1: exact values at 15 degrees', { b: r`Find the exact values of $\sin 15^\circ$, $\cos 15^\circ$ and $\tan 15^\circ$.`, ul: [r`**Write —** $15^\circ = 45^\circ - 30^\circ$`, r`**Sine —** $\dfrac{\sqrt{2}}{2}\cdot\dfrac{\sqrt{3}}{2} - \dfrac{\sqrt{2}}{2}\cdot\dfrac{1}{2} = \dfrac{\sqrt{6} - \sqrt{2}}{4}$`, r`**Tangent —** $\dfrac{1 - \frac{1}{\sqrt{3}}}{1 + \frac{1}{\sqrt{3}}} = 2 - \sqrt{3}$`.replace(r`\dfrac{1 - \frac{1}{\sqrt{3}}}{1 + \frac{1}{\sqrt{3}}}`, r`\dfrac{1 - \dfrac{1}{\sqrt{3}}}{1 + \dfrac{1}{\sqrt{3}}}`)], v: wB1, n: 'Write fifteen degrees as forty-five minus thirty. For the sine, take sine forty-five cosine thirty minus cosine forty-five sine thirty; the products are root six over four and root two over four, giving root six minus root two over four. The cosine has a plus between the products. For the tangent, divide, and rationalise the denominator to get two minus root three.' }),
    sl('check', 'Quick check: an exact value', { b: 'Find the exact value of sine of seventy-five degrees.', chk: 'm17', n: 'Write seventy-five as forty-five plus thirty.' }),
    sl('example', 'Worked example 2: given sin x and cos y', { b: r`$\sin x = \dfrac{8}{17}$ with $x$ in quadrant II and $\cos y = -\dfrac{3}{5}$ with $y$ in quadrant III. Find $\sin(x + y)$, $\cos(x + y)$ and $\tan(x + y)$.`, ul: [r`**First the missing ratios —** $\cos x = -\dfrac{15}{17}$, $\sin y = -\dfrac{4}{5}$`, r`**Sine —** $\dfrac{8}{17}\left(-\dfrac{3}{5}\right) + \left(-\dfrac{15}{17}\right)\left(-\dfrac{4}{5}\right) = \dfrac{36}{85}$`, r`**Cosine —** $\dfrac{45}{85} + \dfrac{32}{85} = \dfrac{77}{85}$; **tangent —** $\dfrac{36}{77}$`], v: wB2, n: 'The two missing ratios come first, with signs from the quadrants. Cosine x is minus fifteen over seventeen, and sine y is minus four over five. Then the sine of the sum is sine x cosine y plus cosine x sine y, which is thirty-six over eighty-five. The cosine of the sum is seventy-seven over eighty-five, and the tangent is their ratio, thirty-six over seventy-seven. As a check, thirty-six squared plus seventy-seven squared is eighty-five squared.' }),
    sl('concept', 'Double angle formulae', { b: r`Put $y = x$ in the sum formulae. The cosine has **three** forms, so choose the one that suits the given information.`, v: tDbl, n: 'Set y equal to x in the sum formulae. Sine two x is two sine x cosine x. Cosine two x is cosine squared minus sine squared, and using sine squared plus cosine squared equals one this also equals two cosine squared minus one, or one minus two sine squared. Tangent two x is two tangent x over one minus tangent squared x. Choose the cosine form that matches what you are given.' }),
    sl('diagram', 'Why sin 2x is not 2 sin x', { b: r`$\sin 2x$ runs through **two** waves while $\sin x$ runs through one. Neither is a simple multiple of the other: $\sin 2x = 2\sin x\cos x$.`, v: pDbl, n: 'A frequent error is to write sine two x as two sine x. The graphs show why this is wrong. Sine two x completes two full waves in the interval where sine x completes one, and its largest value is still one, not two. The correct rule is sine two x equals two sine x cosine x. At pi over four, for instance, sine two x is one.' }),
    sl('example', 'Worked example 3: double angles from sin x', { b: r`If $\sin x = \dfrac{20}{29}$ and $x$ is in quadrant II, find $\sin 2x$, $\cos 2x$ and $\tan 2x$.`, ul: [r`**Cosine first —** $\cos x = -\dfrac{21}{29}$`, r`**Sine —** $2\cdot\dfrac{20}{29}\cdot\left(-\dfrac{21}{29}\right) = -\dfrac{840}{841}$`, r`**Cosine —** $\dfrac{441 - 400}{841} = \dfrac{41}{841}$; **tangent —** $-\dfrac{840}{41}$`], v: wB3, n: 'Start with the cosine of x: it is negative in the second quadrant, so minus twenty-one over twenty-nine. Sine two x is two times twenty over twenty-nine times minus twenty-one over twenty-nine, which is minus eight hundred and forty over eight hundred and forty-one. Cosine two x is four hundred and forty-one minus four hundred, over eight hundred and forty-one, so forty-one over eight hundred and forty-one. Tangent is their ratio.' }),
    sl('check', 'Quick check: sine of a double angle', { b: 'Cosine x is twelve thirteenths and x is in the fourth quadrant. Find sine two x.', chk: 'm19', n: 'Find the sine of x first, with its sign.' }),
    sl('concept', 'Triple angle formulae', { b: r`Write $3x = 2x + x$, apply the sum formula and then the double-angle formulae. The curves of $\sin 3x$ and $3\sin x - 4\sin^3 x$ coincide.`, v: pTri, m: [r`\sin 3x = 3\sin x - 4\sin^3 x`, r`\cos 3x = 4\cos^3 x - 3\cos x`], n: 'To triple an angle, write three x as two x plus x. Apply the sum formula, then the double angle formulae, and reduce everything to sine alone, or cosine alone. You get sine three x equals three sine x minus four sine cubed x, and cosine three x equals four cosine cubed x minus three cosine x. The graph shows two curves lying exactly on top of each other.' }),
    sl('example', 'Worked example 4: triple angle values', { b: r`Find $\tan 3x$ when $\tan x = \dfrac{1}{2}$, and $\cos 3x$ when $\cos x = \dfrac{3}{4}$.`, ul: [r`**Tangent —** $\dfrac{3\tan x - \tan^3 x}{1 - 3\tan^2 x} = \dfrac{\frac{3}{2} - \frac{1}{8}}{1 - \frac{3}{4}} = \dfrac{11}{2}$`.replace(r`\dfrac{\frac{3}{2} - \frac{1}{8}}{1 - \frac{3}{4}}`, r`\dfrac{\dfrac{3}{2} - \dfrac{1}{8}}{1 - \dfrac{3}{4}}`), r`**Cosine —** $4\cdot\dfrac{27}{64} - 3\cdot\dfrac{3}{4} = \dfrac{27}{16} - \dfrac{9}{4} = -\dfrac{9}{16}$`], v: wB4, n: 'For the tangent, use three tangent x minus tangent cubed x over one minus three tangent squared x. With tangent x equal to one half the top is three halves minus one eighth, which is eleven eighths, and the bottom is one quarter, so the result is eleven halves. For the cosine, four times twenty-seven sixty-fourths minus nine fourths gives minus nine sixteenths.' }),
    sl('check', 'Quick check: not an identity', { b: 'True or false: the sine of two x equals two sine x for every real x.', chk: 'tf2', n: 'Try x equal to pi over two.' }),
    sl('concept', 'General solutions (formative topic)', { b: r`An equation like $\sin y = \sin a$ has **infinitely many** solutions because the functions repeat. Taught for understanding; not assessed in the annual paper.`, v: tGen, n: 'Because sine, cosine and tangent repeat, an equation such as sine y equals sine a has infinitely many solutions. These are described by one formula with an integer n. For sine, y equals n pi plus minus one to the n times a. For cosine, y equals two n pi plus or minus a. For tangent, y equals n pi plus a. This topic is for your understanding and is not assessed in the annual paper.' }),
    sl('diagram', 'Why a sine equation has two solutions per turn', { b: r`The line $y = \dfrac{1}{2}$ meets the sine wave **twice** in every period: at $\dfrac{\pi}{6}$ and $\dfrac{5\pi}{6}$, then $2\pi$ later, and so on.`, v: pHalf, n: 'To solve sine x equals one half, draw the line at height one half across the sine wave. It cuts each wave twice, once on the way up and once on the way down, at pi over six and five pi over six. Two pi later the same two solutions appear again. The marked points show four of them. The general solution describes all of them with a single formula.' }),
    sl('example', 'Worked example 5: a sine equation (formative)', { b: r`Solve $\sin x = -\dfrac{\sqrt{3}}{2}$ for $0 \le x \le 2\pi$, and write the general solution.`, ul: [r`**Reference angle —** $\dfrac{\pi}{3}$`, r`**Quadrants —** sine is negative in III and IV: $x = \dfrac{4\pi}{3}$, $\dfrac{5\pi}{3}$`, r`**General —** $x = n\pi + (-1)^n\left(-\dfrac{\pi}{3}\right)$`], v: wB5, n: 'Find the reference angle: sine of pi over three is root three over two, so the reference angle is pi over three. Sine is negative in the third and fourth quadrants. The solutions in zero to two pi are pi plus pi over three, which is four pi over three, and two pi minus pi over three, which is five pi over three. The general solution uses a equal to minus pi over three in the sine formula.' }),
    sl('check', 'Quick check: a tangent equation', { b: 'Find the general solution of the equation tangent x equals root three.', chk: 'm22', n: 'Tangent has period pi, so one family of solutions is enough.' }),
    sl('summary', 'Summary', { ul: [r`$\cos(x \mp y) = \cos x\cos y \pm \sin x\sin y$; $\sin(x \pm y) = \sin x\cos y \pm \cos x\sin y$`, r`$\tan(x \pm y) = \dfrac{\tan x \pm \tan y}{1 \mp \tan x\tan y}$ when defined`, r`$\sin 2x = 2\sin x\cos x$; $\cos 2x = \cos^2 x - \sin^2 x = 2\cos^2 x - 1 = 1 - 2\sin^2 x$`, r`$\sin 3x = 3\sin x - 4\sin^3 x$; $\cos 3x = 4\cos^3 x - 3\cos x$`, r`General solutions (formative): $\sin y = \sin a$, $\cos y = \cos a$, $\tan y = \tan a$`], v: summary2, n: 'To sum up. Everything starts from the cosine of a difference. The other sum and difference formulae follow. Putting y equal to x gives the double angle formulae, with three forms for the cosine. Writing three x as two x plus x gives the triple angle formulae. Finally, because the functions repeat, trigonometric equations have general solutions with an integer n.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Exact value (2 marks):** formula, four standard values, simplified surd', '**Given ratio (2–3 marks):** missing ratio with sign by quadrant, then the formula', '**Proof (3 marks):** expand, use the identity, state the final form', '**Mistake:** $\\cos(x + y) = \\cos x + \\cos y$, $\\sin 2x = 2\\sin x$, or ignoring the quadrant', '**Light topic:** general solutions are formative only'], n: 'For exact values, write the formula, substitute the four standard values and simplify the surd. For given-ratio questions, find the missing ratio with its sign from the quadrant before using any formula. For proofs, expand, use sine squared plus cosine squared equals one, and state the final form. Common slips: treating cosine of a sum as a sum of cosines, writing sine two x as two sine x, and forgetting the quadrant.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'cbse-11-mathematics-ch03', version: 1, title: 'Trigonometric Functions — chapter notes', language: 'en',
  sections: [
    { heading: '1. Angles: degrees and radians', body_md: r`A **full turn** is $360^\circ$ or $2\pi$ radians, so $\pi$ radians $= 180^\circ$. Positive angles are measured anticlockwise from the positive $x$-axis, negative angles clockwise.\n\nOne **radian** is the angle at the centre subtended by an arc whose length equals the radius ($1$ rad $\approx 57.3^\circ$).\n\n- Degrees to radians: multiply by $\dfrac{\pi}{180}$. Radians to degrees: multiply by $\dfrac{180}{\pi}$.\n- A plain number such as $2$ means $2$ radians.\n- Learn: $30^\circ = \dfrac{\pi}{6}$, $45^\circ = \dfrac{\pi}{4}$, $60^\circ = \dfrac{\pi}{3}$, $90^\circ = \dfrac{\pi}{2}$, $180^\circ = \pi$.`, key_terms: [{ term: 'Radian', definition_md: 'The angle subtended at the centre by an arc equal in length to the radius.' }, { term: 'Full turn', definition_md: r`$360^\circ = 2\pi$ radians.` }], formulas: [{ latex: r`\text{radian} = \text{degree} \times \dfrac{\pi}{180}`, label: 'Degrees to radians' }, { latex: r`\text{degree} = \text{radian} \times \dfrac{180}{\pi}`, label: 'Radians to degrees' }], visual: tConv, visuals: [oneRad, tTurns, we1], topic_ids: [topic(1)] },
    { heading: '2. Arc length', body_md: r`On a circle of radius $r$, an arc that subtends the angle $\theta$ **radians** at the centre has length $l = r\theta$. If $\theta$ is given in degrees, convert it first: $l = r \times \dfrac{\pi\theta}{180}$.\n\nThe same formula gives $\theta = \dfrac{l}{r}$ and $r = \dfrac{l}{\theta}$. For a wheel that rolls without slipping, the distance rolled is the arc length turned.\n\nExample: $r = 7$ m, $\theta = 100^\circ = \dfrac{5\pi}{9}$ rad gives $l = \dfrac{35\pi}{9} \approx 12.22$ m.`, key_terms: [{ term: 'Arc length', definition_md: r`$l = r\theta$ with $\theta$ in radians.` }], formulas: [{ latex: r`l = r\theta`, label: 'Arc length' }], visual: arcFig, visuals: [we2], topic_ids: [topic(1)] },
    { heading: '3. The unit circle and signs', body_md: r`On the **unit circle** (radius $1$, centre $O$), the point $P(\theta)$ reached by turning $\theta$ from the positive $x$-axis is $(\cos\theta, \sin\theta)$. Then $\tan\theta = \dfrac{\sin\theta}{\cos\theta}$ ($\cos\theta \ne 0$), and $\operatorname{cosec}\theta$, $\sec\theta$, $\cot\theta$ are the reciprocals of $\sin\theta$, $\cos\theta$, $\tan\theta$.\n\nBecause $P$ is on the circle, $\sin^2\theta + \cos^2\theta = 1$, hence $1 + \tan^2\theta = \sec^2\theta$ and $1 + \cot^2\theta = \operatorname{cosec}^2\theta$.\n\n**Signs:** quadrant I all positive; II only $\sin$ (and cosec); III only $\tan$ (and cot); IV only $\cos$ (and sec).\n\nGiven one ratio and the quadrant, find the others from $\sin^2\theta + \cos^2\theta = 1$, choosing the sign from the quadrant.`, key_terms: [{ term: 'Unit circle', definition_md: 'The circle of radius 1 centred at the origin.' }, { term: 'Quadrant rule', definition_md: 'All, Sine, Tangent, Cosine are the positive functions in quadrants I to IV.' }], formulas: [{ latex: r`P(\theta) = (\cos\theta, \sin\theta)`, label: 'Unit circle' }, { latex: r`\sin^2\theta + \cos^2\theta = 1`, label: 'Basic identity' }], visual: circle120, visuals: [quadFig, we3], topic_ids: [topic(2)] },
    { heading: '4. Standard values, domain, range and period', body_md: r`Exact values at $0^\circ, 30^\circ, 45^\circ, 60^\circ, 90^\circ$ are in the table; angles in other quadrants use the **reference angle** and the sign.\n\n- $\sin x$ and $\cos x$: domain $\mathbb{R}$, range $[-1, 1]$, period $2\pi$.\n- $\tan x$: domain $\mathbb{R} - \left\{(2n+1)\dfrac{\pi}{2}\right\}$, range $\mathbb{R}$, period $\pi$.\n- $\sin$ and $\tan$ are **odd**, $\cos$ is **even**.\n\nTo find a period, look for the smallest positive $p$ with $f(x + p) = f(x)$; e.g. $|\sin x|$ has period $\pi$.`, key_terms: [{ term: 'Period', definition_md: r`The smallest positive $p$ with $f(x + p) = f(x)$.` }, { term: 'Reference angle', definition_md: 'The acute angle between the terminal side and the horizontal axis.' }], formulas: [{ latex: r`\sin(x + 2\pi) = \sin x,\quad \tan(x + \pi) = \tan x`, label: 'Periodicity' }], visual: tStd, visuals: [tProps], topic_ids: [topic(2)] },
    { heading: '5. Graphs of sine, cosine and tangent', body_md: r`- $y = \sin x$: a wave through the origin, zeros at $n\pi$, peaks $1$ at $\dfrac{\pi}{2} + 2n\pi$, troughs $-1$ at $\dfrac{3\pi}{2} + 2n\pi$.\n- $y = \cos x$: starts at $1$, zeros at $\dfrac{\pi}{2} + n\pi$, peaks at $2n\pi$, troughs at $\pi + 2n\pi$.\n- $y = \tan x$: branches between vertical asymptotes $x = \dfrac{\pi}{2} + n\pi$, zeros at $n\pi$, passes $\left(\dfrac{\pi}{4}, 1\right)$.\n\nWhen sketching, mark **every** zero in the range, the peaks and troughs, and the asymptotes of tangent.`, key_terms: [{ term: 'Asymptote', definition_md: r`A line a graph approaches without meeting; for $\tan x$ the lines $x = \dfrac{\pi}{2} + n\pi$.` }], formulas: [{ latex: r`\cos x = \sin\left(x + \dfrac{\pi}{2}\right)`, label: 'Cosine as a shifted sine' }], visual: pSin, visuals: [pCos, pTan], topic_ids: [topic(2)] },
    { heading: '6. Allied angles', body_md: r`Allied angles are $\dfrac{\pi}{2} \pm x$, $\pi \pm x$, $2\pi - x$, $-x$ and whole turns added. Use a **reference angle**, then the sign from the quadrant (imagine $x$ small and positive).\n\n- $\sin(\pi - x) = \sin x$, $\cos(\pi - x) = -\cos x$, $\tan(\pi - x) = -\tan x$.\n- $\sin(\pi + x) = -\sin x$, $\cos(\pi + x) = -\cos x$, $\tan(\pi + x) = \tan x$.\n- $\sin\left(\dfrac{\pi}{2} - x\right) = \cos x$, $\cos\left(\dfrac{\pi}{2} - x\right) = \sin x$.\n- $\sin(-x) = -\sin x$, $\cos(-x) = \cos x$.\n\nFor large angles first subtract whole turns ($360^\circ$ for $\sin$, $\cos$; $180^\circ$ for $\tan$): $\sin 780^\circ = \sin 60^\circ$.`, key_terms: [{ term: 'Allied angle', definition_md: r`An angle that differs from $x$ by a multiple of a quarter turn or is $-x$.` }], formulas: [{ latex: r`\sin(\pi - x) = \sin x,\quad \cos(\pi - x) = -\cos x`, label: 'Mirror in the y-axis' }], visual: allied, visuals: [alliedTable, we4], topic_ids: [topic(2)] },
    { heading: '7. Sum and difference formulae', body_md: r`From $\cos(x - y) = \cos x\cos y + \sin x\sin y$ (two equal chords of the unit circle) all six formulae follow.\n\n- $\sin(x \pm y) = \sin x\cos y \pm \cos x\sin y$.\n- $\cos(x \pm y) = \cos x\cos y \mp \sin x\sin y$.\n- $\tan(x \pm y) = \dfrac{\tan x \pm \tan y}{1 \mp \tan x\tan y}$, when all the tangents are defined and the denominator is not zero.\n\nUse them for exact values ($15^\circ = 45^\circ - 30^\circ$, $75^\circ = 45^\circ + 30^\circ$, $105^\circ = 60^\circ + 45^\circ$) and for given-ratio questions: find the missing sine or cosine with its sign first.`, key_terms: [{ term: 'Compound angle', definition_md: r`An angle of the form $x \pm y$.` }], formulas: [{ latex: r`\sin(x + y) = \sin x\cos y + \cos x\sin y`, label: 'Sine of a sum' }, { latex: r`\cos(x + y) = \cos x\cos y - \sin x\sin y`, label: 'Cosine of a sum' }, { latex: r`\tan(x + y) = \dfrac{\tan x + \tan y}{1 - \tan x\tan y}`, label: 'Tangent of a sum' }], visual: tSum, visuals: [chordFig, tTanCond, wB1, wB2], topic_ids: [topic(3)] },
    { heading: '8. Double and triple angles; general solutions', body_md: r`Putting $y = x$: $\sin 2x = 2\sin x\cos x$; $\cos 2x = \cos^2 x - \sin^2 x = 2\cos^2 x - 1 = 1 - 2\sin^2 x$; $\tan 2x = \dfrac{2\tan x}{1 - \tan^2 x}$.\n\nWriting $3x = 2x + x$: $\sin 3x = 3\sin x - 4\sin^3 x$; $\cos 3x = 4\cos^3 x - 3\cos x$; $\tan 3x = \dfrac{3\tan x - \tan^3 x}{1 - 3\tan^2 x}$.\n\n**General solutions (formative only; not assessed in the annual paper):** $\sin y = \sin a \Rightarrow y = n\pi + (-1)^n a$; $\cos y = \cos a \Rightarrow y = 2n\pi \pm a$; $\tan y = \tan a \Rightarrow y = n\pi + a$ ($n \in \mathbb{Z}$). For solutions in an interval, find the reference angle and the quadrants.`, key_terms: [{ term: 'Multiple angle', definition_md: r`An angle $2x$, $3x$, … that is a multiple of $x$.` }, { term: 'General solution', definition_md: 'A formula with an integer n giving all solutions of an equation.' }], formulas: [{ latex: r`\sin 2x = 2\sin x\cos x`, label: 'Double angle (sine)' }, { latex: r`\cos 2x = 1 - 2\sin^2 x`, label: 'Double angle (cosine)' }, { latex: r`\sin 3x = 3\sin x - 4\sin^3 x`, label: 'Triple angle (sine)' }], visual: tDbl, visuals: [pDbl, wB3, tTri, pTri, wB4, tGen, pHalf, wB5], topic_ids: [topic(3), topic(4)] },
  ],
  exam_tips_md: r`**How marks are awarded**\n- *Conversion and arc length (1–3 marks):* factor, simplified fraction, convert before $l = r\theta$, units.\n- *Signs and exact values (2–3 marks):* quadrant, reference angle, sign, simplified surd.\n- *Graph (2 marks):* shape, zeros, peaks and troughs, period, asymptotes of tangent.\n- *Given-ratio questions (2–3 marks):* missing ratio with sign from the quadrant, formula, value.\n- *Proof (3–5 marks):* expand, use $\sin^2 x + \cos^2 x = 1$, state the result.\n- *Equations (formative):* reference angle, quadrants, then the general formula.\n\n**Common mistakes**\n1. Using $l = r\theta$ with $\theta$ in degrees.\n2. Wrong signs in quadrants II and III; forgetting that $\sin$ is odd and $\cos$ even.\n3. Giving tangent the period $2\pi$ (it is $\pi$) or domain $\mathbb{R} - \{n\pi\}$.\n4. $\cos(x + y) = \cos x + \cos y$, or the wrong sign between the products.\n5. $\sin 2x = 2\sin x$ (it is $2\sin x\cos x$).\n6. Choosing the wrong form of $\cos 2x$ when only $\sin x$ or $\tan x$ is given.\n7. Forgetting the quadrant when finding the missing ratio.\n8. General solutions are a formative topic: the board does not assess them in the annual paper.`,
  status: 'draft', provenance: d1.provenance,
};

