// exact identities at all multiples of 15 degrees, asserted once for the whole chapter
{
  let n = 0;
  for (const A of T.ALL15) {
    must(eq(sinD(3 * A), sub(mul(3, sinD(A)), mul(4, T.pow(sinD(A), 3)))) && eq(cosD(3 * A), sub(mul(4, T.pow(cosD(A), 3)), mul(3, cosD(A)))) && eq(sinD(2 * A), mul(2, mul(sinD(A), cosD(A)))), `triple/double at ${A}`);
    must(eq(add(mul(sinD(A), sinD(A)), mul(cosD(A), cosD(A))), el(1)), `pythagoras at ${A}`);
    for (const B of T.ALL15) {
      must(eq(sinD(A + B), add(mul(sinD(A), cosD(B)), mul(cosD(A), sinD(B)))) && eq(cosD(A + B), sub(mul(cosD(A), cosD(B)), mul(sinD(A), sinD(B)))) && eq(cosD(A - B), add(mul(cosD(A), cosD(B)), mul(sinD(A), sinD(B)))) && eq(sinD(A - B), sub(mul(sinD(A), cosD(B)), mul(cosD(A), sinD(B)))), `sum/difference at ${A}, ${B}`);
      if (T.tanDefined(A) && T.tanDefined(B) && T.tanDefined(A + B) && !eq(mul(tanD(A), tanD(B)), el(1))) { must(eq(tanD(A + B), div(add(tanD(A), tanD(B)), sub(el(1), mul(tanD(A), tanD(B))))), `tan sum at ${A}, ${B}`); n++; }
    }
  }
  must(n > 400, 'tan sum cases');
  release.build.checks.exact = `sum, difference, double, triple angle and Pythagoras identities hold exactly (surd arithmetic) at all 24 x 24 pairs of multiples of 15 degrees; ${n} tangent-sum pairs`;
}
